package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.deser.std.NullifyingDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeIdResolver;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class TypeDeserializerBase__deserializeWithNativeTypeId_TriageGen0Test {

    private TestableTypeDeserializer sut;
    private JsonParser mockParser;
    private DeserializationContext mockContext;
    private JavaType mockBaseType;

    // Concrete implementation to allow testing protected method and mocking internal calls
    private static class TestableTypeDeserializer extends TypeDeserializerBase {
        protected JsonDeserializer<Object> mockDeser;
        protected JsonDeserializer<Object> mockDefaultDeser;
        protected boolean findDefaultImplCalled = false;
        protected boolean findDeserializerCalled = false;
        private String lastTypeIdStr;

        protected TestableTypeDeserializer(JavaType baseType, TypeIdResolver idRes, String typePropertyName, boolean typeIdVisible, JavaType defaultImpl) {
            super(baseType, idRes, typePropertyName, typeIdVisible, defaultImpl);
        }

        @Override
        public TypeDeserializer forProperty(com.fasterxml.jackson.databind.BeanProperty prop) {
            return null;
        }

        @Override
        public com.fasterxml.jackson.annotation.JsonTypeInfo.As getTypeInclusion() {
            return null;
        }

        @Override
        public String baseTypeName() {
            return "TestBase";
        }

        @Override
        protected JsonDeserializer<Object> _findDeserializer(DeserializationContext ctxt, String typeId) throws IOException {
            this.findDeserializerCalled = true;
            this.lastTypeIdStr = typeId;
            return mockDeser;
        }

        @Override
        protected JsonDeserializer<Object> _findDefaultImplDeserializer(DeserializationContext ctxt) throws IOException {
            this.findDefaultImplCalled = true;
            return mockDefaultDeser;
        }

        // Expose protected method for testing
        public Object callDeserializeWithNativeTypeId(JsonParser jp, DeserializationContext ctxt, Object typeId) throws IOException {
            return _deserializeWithNativeTypeId(jp, ctxt, typeId);
        }
    }

    @Before
    public void setUp() {
        mockParser = mock(JsonParser.class);
        mockContext = mock(DeserializationContext.class);
        mockBaseType = mock(JavaType.class);

        // Mocking the base class's baseType() behavior via the spy/implementation if needed
        // But since we are using a concrete subclass, we need to ensure baseType() returns something.
        // We'll use a spy or a custom implementation.

        sut = new TestableTypeDeserializer(mockBaseType, mock(com.fasterxml.jackson.databind.jsontype.TypeIdResolver.class), "type", true, null) {
            @Override
            public JavaType baseType() {
                return mockBaseType;
            }
        };
    }

    @Test
    public void testDeserialize_WithNullTypeId_AndDefaultDeserializerFound() throws IOException {
        Object expectedResult = "success";
        sut.mockDefaultDeser = mock(JsonDeserializer.class);
        when(sut.mockDefaultDeser.deserialize(mockParser, mockContext)).thenReturn(expectedResult);

        Object result = sut.callDeserializeWithNativeTypeId(mockParser, mockContext, null);

        assertEquals(expectedResult, result);
        verify(sut.mockDefaultDeser).deserialize(mockParser, mockContext);
        verify(mockContext, never()).reportInputMismatch(any(), anyString());
    }

    @Test
    public void testDeserialize_WithNullTypeId_AndNoDefaultDeserializerFound() throws IOException {
        sut.mockDefaultDeser = null;
        String errorMsg = "No (native) type id found";
        when(mockContext.reportInputMismatch(eq(mockBaseType), anyString())).thenReturn("error_object");

        Object result = sut.callDeserializeWithNativeTypeId(mockParser, mockContext, null);

        assertEquals("error_object", result);
        verify(mockContext).reportInputMismatch(eq(mockBaseType), contains(errorMsg));
    }

    @Test
    public void testDeserialize_WithStringTypeId() throws IOException {
        String typeId = "MyType";
        Object expectedResult = new Object();
        sut.mockDeser = mock(JsonDeserializer.class);
        when(sut.mockDeser.deserialize(mockParser, mockContext)).thenReturn(expectedResult);

        Object result = sut.callDeserializeWithNativeTypeId(mockParser, mockContext, typeId);

        assertEquals(expectedResult, result);
        assertEquals("MyType", sut.lastTypeIdStr);
        verify(sut.mockDeser).deserialize(mockParser, mockContext);
    }

    @Test
    public void testDeserialize_WithIntegerTypeId() throws IOException {
        Integer typeId = 123;
        Object expectedResult = new Object();
        sut.mockDeser = mock(JsonDeserializer.class);
        when(sut.mockDeser.deserialize(mockParser, mockContext)).thenReturn(expectedResult);

        Object result = sut.callDeserializeWithNativeTypeId(mockParser, mockContext, typeId);

        assertEquals(expectedResult, result);
        assertEquals("123", sut.lastTypeIdStr);
        verify(sut.mockDeser).deserialize(mockParser, mockContext);
    }

    @Test
    public void testDeserialize_WithNonStringObjectTypeId() throws IOException {
        Object typeId = new Object();
        String typeIdStr = typeId.toString();
        Object expectedResult = new Object();
        sut.mockDeser = mock(JsonDeserializer.class);
        when(sut.mockDeser.deserialize(mockParser, mockContext)).thenReturn(expectedResult);

        Object result = sut.callDeserializeWithNativeTypeId(mockParser, mockContext, typeId);

        assertEquals(expectedResult, result);
        assertEquals(typeIdStr, sut.lastTypeIdStr);
        verify(sut.mockDeser).deserialize(mockParser, mockContext);
    }
}
